param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$owners=@('System.IDisposable','System.IComparable','System.IFormattable','System.IFormatProvider','System.ICloneable');$methodNames=@('Dispose','CompareTo','ToString','GetFormat','Clone');$profiles=@('null','empty','object','int','nullElement','objectNull','twoObjects','cloneable')
function Types([string]$Profile){switch($Profile){'null'{$a=$null};'empty'{$a=[type[]]@()};'object'{$a=[type[]]@([object])};'int'{$a=[type[]]@([int])};'nullElement'{$a=[type[]]@($null)};'objectNull'{$a=[type[]]@([object],$null)};'twoObjects'{$a=[type[]]@([object],[object])};'cloneable'{$a=[type[]]@([ICloneable])}};return ,$a}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$make=[Reflection.MethodInfo].GetMethod('MakeGenericMethod',[type[]]@([type[]]));$rows=[Collections.Generic.List[object]]::new()
for($i=0;$i -lt $owners.Count;$i++){$t=[type]::GetType($owners[$i],$true);$m=$t.GetMethod($methodNames[$i]);try{$v=$m.GetGenericMethodDefinition();$r=[ordered]@{ok=$true;name=$v.Name}}catch{$r=Failure $_};$rows.Add([ordered]@{owner=$owners[$i];method=$methodNames[$i];descriptor=$m.ToString();route='definition';profile='empty';result=$r})
 foreach($profile in $profiles){$arguments=[object[]]::new(1);$arguments[0]=(Types $profile);try{$v=$make.Invoke($m,$arguments);$r=[ordered]@{ok=$true;name=$v.Name}}catch{$r=Failure $_};$rows.Add([ordered]@{owner=$owners[$i];method=$methodNames[$i];descriptor=$m.ToString();route='make';profile=$profile;result=$r})}
}
if($rows.Count -ne 45){throw 'Wrong generic guard matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';owners=$owners;methods=$methodNames;profiles=$profiles;rows=$rows.ToArray();qualification='SELECTED_NONGENERIC_INTERFACE_METHOD_GUARD_DIAGNOSTICS_ONLY; GENERIC_CONSTRUCTION_INVOCATION_FULL_REFLECTION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 20 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS nongeneric MethodInfo guards: five methods, 45 cases'
